export const FORECAST_CARD_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Road to Six forecast card</title>\n<style>\n  :root { color-scheme: light dark; }\n  * { box-sizing: border-box; }\n  body {\n    margin: 0; padding: 16px;\n    font-family: var(--font-sans, system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif);\n    font-size: var(--font-text-md-size, 15px); line-height: 1.45;\n    color: var(--color-text-primary, CanvasText); background: var(--color-background-primary, Canvas);\n  }\n  main { max-width: 560px; margin: 0 auto; }\n  h1 { font-size: var(--font-heading-md-size, 20px); margin: 0 0 2px; line-height: 1.25; }\n  h2 { font-size: var(--font-text-md-size, 15px); margin: 20px 0 6px; }\n  p { margin: 0 0 6px; }\n  .eyebrow { font-size: 12px; letter-spacing: 0.04em; text-transform: uppercase; }\n  /* Fallback keeps secondary text above a 4.5 to 1 contrast ratio in light and dark schemes. */\n  .muted, .eyebrow { color: var(--color-text-secondary, color-mix(in srgb, CanvasText 70%, Canvas)); }\n  .small { font-size: 13px; }\n  .figure { display: flex; align-items: baseline; gap: 10px; margin: 14px 0 8px; }\n  .figure strong { font-size: 44px; line-height: 1; font-variant-numeric: tabular-nums; }\n  .track {\n    position: relative; height: 14px; border-radius: 7px; margin: 0 0 8px;\n    background: var(--color-background-secondary, rgba(128, 128, 128, 0.22));\n  }\n  .band { position: absolute; top: 0; bottom: 0; border-radius: 7px; background: rgba(128, 128, 128, 0.38); }\n  .marker {\n    position: absolute; top: -4px; bottom: -4px; width: 4px; margin-left: -2px; border-radius: 2px;\n    background: var(--color-text-primary, CanvasText); transition: left 0.2s ease;\n  }\n  ul { list-style: none; margin: 0; padding: 0; }\n  .drivers li { display: flex; justify-content: space-between; gap: 12px; padding: 4px 0; border-bottom: 1px solid var(--color-border-secondary, rgba(128, 128, 128, 0.3)); }\n  .drivers span:last-child { font-variant-numeric: tabular-nums; white-space: nowrap; }\n  .control { display: grid; grid-template-columns: minmax(0, 11em) 1fr 3.2em; align-items: center; gap: 8px; margin: 6px 0; }\n  .control output { text-align: right; font-variant-numeric: tabular-nums; }\n  input[type=\"range\"] { width: 100%; margin: 0; accent-color: var(--color-text-primary, CanvasText); }\n  button {\n    font: inherit; padding: 6px 12px; margin-top: 6px; border-radius: 6px; cursor: pointer;\n    color: inherit; background: transparent; border: 1px solid var(--color-border-primary, GrayText);\n  }\n  button:disabled, input:disabled { cursor: not-allowed; opacity: 0.55; }\n  :focus-visible { outline: 2px solid var(--color-ring-primary, Highlight); outline-offset: 2px; }\n  .chips { display: flex; flex-wrap: wrap; gap: 6px; margin: 16px 0 8px; }\n  .chips li { font-size: 12px; padding: 2px 8px; border-radius: 10px; border: 1px solid var(--color-border-secondary, rgba(128, 128, 128, 0.45)); }\n  .chips li[data-tone=\"warn\"] { border-color: var(--color-border-warning, #b45309); color: var(--color-text-warning, #b45309); }\n  a { color: inherit; }\n  [hidden] { display: none !important; }\n  @media (max-width: 420px) { .control { grid-template-columns: 1fr 3.2em; } .control label { grid-column: 1 / -1; } }\n  @media (prefers-reduced-motion: reduce) { .marker { transition: none; } }\n</style>\n</head>\n<body>\n<main aria-labelledby=\"title\">\n  <header>\n    <p class=\"eyebrow\">Road to Six, football-only model</p>\n    <h1 id=\"title\">Waiting for the forecast</h1>\n    <p id=\"kickoff\" class=\"muted small\"></p>\n  </header>\n\n  <div id=\"status\" role=\"status\" aria-live=\"polite\">\n    <section id=\"result\" hidden>\n      <p class=\"figure\"><strong id=\"percent\"></strong><span class=\"muted\">Cowboys win probability</span></p>\n      <div id=\"track\" class=\"track\" role=\"img\" aria-label=\"\">\n        <div id=\"band\" class=\"band\"></div><div id=\"marker\" class=\"marker\"></div>\n      </div>\n      <p id=\"summary\" class=\"muted small\"></p>\n    </section>\n    <p id=\"message\">This card shows a forecast once the host shares a tool result.</p>\n  </div>\n\n  <section id=\"drivers-section\" aria-labelledby=\"drivers-title\" hidden>\n    <h2 id=\"drivers-title\">What moves the estimate</h2>\n    <ul id=\"drivers\" class=\"drivers\"></ul>\n  </section>\n\n  <form id=\"controls\" aria-labelledby=\"controls-title\" hidden>\n    <h2 id=\"controls-title\">What if</h2>\n    <p id=\"controls-help\" class=\"muted small\">Availability from 0 to 100 percent. 100 is the unchanged baseline.</p>\n    <div class=\"control\"><label for=\"c-quarterback\">Dak Prescott</label><input id=\"c-quarterback\" name=\"quarterback\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"100\"><output for=\"c-quarterback\">100%</output></div>\n    <div class=\"control\"><label for=\"c-lamb\">CeeDee Lamb</label><input id=\"c-lamb\" name=\"lamb\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"100\"><output for=\"c-lamb\">100%</output></div>\n    <div class=\"control\"><label for=\"c-pickens\">George Pickens</label><input id=\"c-pickens\" name=\"pickens\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"100\"><output for=\"c-pickens\">100%</output></div>\n    <div class=\"control\"><label for=\"c-williams\">Javonte Williams</label><input id=\"c-williams\" name=\"williams\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"100\"><output for=\"c-williams\">100%</output></div>\n    <div class=\"control\"><label for=\"c-defense\">Defensive core</label><input id=\"c-defense\" name=\"defense\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"100\"><output for=\"c-defense\">100%</output></div>\n    <div class=\"control\"><label for=\"c-opponentStar\">Opponent production leader</label><input id=\"c-opponentStar\" name=\"opponentStar\" type=\"range\" min=\"0\" max=\"100\" step=\"5\" value=\"100\"><output for=\"c-opponentStar\">100%</output></div>\n    <button id=\"reset\" type=\"button\">Reset to baseline</button>\n  </form>\n\n  <footer>\n    <ul id=\"chips\" class=\"chips\" aria-label=\"Data freshness\"></ul>\n    <p id=\"evaluation\" class=\"muted small\"></p>\n    <p id=\"notice\" class=\"muted small\">Educational analytics from an unofficial fan project that is not affiliated with the Dallas Cowboys or the NFL. Not betting, wagering, or fantasy start or sit advice.</p>\n    <p class=\"small\"><a id=\"model-card\" href=\"https://github.com/erlawler/road-to-six/blob/main/docs/model-card.md\" target=\"_blank\" rel=\"noopener noreferrer\">Model card and limits</a></p>\n  </footer>\n</main>\n<script>\n(() => {\n  \"use strict\";\n  // A dependency-free MCP Apps view (extension revision 2026-01-26).\n  // It speaks JSON-RPC 2.0 with its host over postMessage, renders only with\n  // textContent, loads nothing external, and makes no network requests.\n  const APP_PROTOCOL_VERSION = \"2026-01-26\";\n  const TOOL_NAME = \"get_football_forecast\";\n  const CONTROL_KEYS = [\"quarterback\", \"lamb\", \"pickens\", \"williams\", \"defense\", \"opponentStar\"];\n  const host = window.parent;\n  const $ = (id) => document.getElementById(id);\n  const form = $(\"controls\");\n  const pending = new Map();\n  let nextId = 1, debounce = 0, latestCall = 0, canCallTools = false, canOpenLinks = false;\n\n  const post = (message) => host.postMessage(message, \"*\");\n  const notify = (method, params) => post({ jsonrpc: \"2.0\", method, params });\n  const request = (method, params) => new Promise((resolve, reject) => {\n    const id = nextId++;\n    pending.set(id, { resolve, reject });\n    post({ jsonrpc: \"2.0\", id, method, params });\n  });\n\n  const percent = (value) => `${Number(value).toFixed(1)}%`;\n  const signed = (value) => `${value > 0 ? \"+\" : \"\"}${Number(value).toFixed(1)}`;\n  const when = (iso) => {\n    const time = Date.parse(iso);\n    // The zone is always shown so a time is never mistaken for another zone's.\n    return Number.isFinite(time) ? new Date(time).toLocaleString(undefined, {\n      month: \"short\", day: \"numeric\", year: \"numeric\", hour: \"numeric\", minute: \"2-digit\", timeZoneName: \"short\",\n    }) : \"unknown\";\n  };\n  const fill = (list, items, build) => {\n    list.replaceChildren(...items.map((item) => { const element = document.createElement(\"li\"); build(element, item); return element; }));\n  };\n\n  function showMessage(text) {\n    $(\"result\").hidden = true;\n    $(\"drivers-section\").hidden = true;\n    $(\"message\").hidden = false;\n    $(\"message\").textContent = text;\n  }\n\n  function setControls(values) {\n    for (const key of CONTROL_KEYS) {\n      const input = form.elements.namedItem(key);\n      const value = typeof values?.[key] === \"number\" && values[key] >= 0 && values[key] <= 100 ? values[key] : 100;\n      input.value = String(value);\n      input.nextElementSibling.textContent = `${Math.round(Number(input.value))}%`;\n    }\n  }\n\n  function readPayload(result) {\n    if (result?.structuredContent && typeof result.structuredContent === \"object\") return result.structuredContent;\n    try { return JSON.parse(result.content.find((item) => item.type === \"text\").text); } catch { return null; }\n  }\n\n  function renderEvidence(data) {\n    const evidence = data.evidence, chips = [];\n    if (evidence.stale) chips.push({ text: \"Stale data\", tone: \"warn\" });\n    if (evidence.status !== \"ok\") chips.push({ text: `Status: ${evidence.status}`, tone: \"warn\" });\n    chips.push({ text: `Verified ${when(evidence.football?.verifiedAt)}` });\n    chips.push({ text: `Read ${when(evidence.observedAt)}` });\n    chips.push({ text: `Data ${evidence.football?.dataVersion ?? \"unknown\"}` });\n    fill($(\"chips\"), chips, (element, chip) => { element.textContent = chip.text; if (chip.tone) element.dataset.tone = chip.tone; });\n    $(\"evaluation\").textContent = data.evaluation?.note ?? \"\";\n    if (typeof evidence.notice === \"string\") $(\"notice\").textContent = evidence.notice;\n  }\n\n  function render(result) {\n    if (!result) return;\n    if (result.isError) return showMessage(result.content?.[0]?.text ?? \"The forecast tool returned an error.\");\n    const data = readPayload(result);\n    if (!data || !data.evidence) return showMessage(\"The forecast result could not be read.\");\n    renderEvidence(data);\n    const matchup = data.matchup;\n    $(\"title\").textContent = matchup ? `Dallas ${matchup.venue === \"away\" ? \"at\" : \"vs\"} ${matchup.opponentName}, Week ${matchup.week}` : \"Dallas Cowboys forecast\";\n    $(\"kickoff\").textContent = matchup?.kickoffAt ? `Kickoff ${when(matchup.kickoffAt)}` : \"\";\n    if (data.status !== \"available\" || !data.forecast) {\n      form.hidden = true;\n      return showMessage(`No forecast is available. ${data.reasons?.[0] ?? data.evidence.reason ?? \"The current matchup is not verified.\"}`);\n    }\n    const forecast = data.forecast, band = forecast.illustrativeBandPercent;\n    $(\"percent\").textContent = percent(forecast.cowboysWinPercent);\n    $(\"marker\").style.left = `${forecast.cowboysWinPercent}%`;\n    $(\"band\").style.left = `${band.low}%`;\n    $(\"band\").style.width = `${Math.max(0, band.high - band.low)}%`;\n    $(\"track\").setAttribute(\"aria-label\", `Estimate ${percent(forecast.cowboysWinPercent)}, illustrative band ${percent(band.low)} to ${percent(band.high)}`);\n    $(\"summary\").textContent = forecast.scenarioApplied\n      ? `Baseline ${percent(forecast.baselinePercent)}. This scenario moves it ${signed(forecast.scenarioDeltaPoints)} points. Illustrative band ${percent(band.low)} to ${percent(band.high)}.`\n      : `Baseline with every control at 100. Illustrative band ${percent(band.low)} to ${percent(band.high)}, not a calibrated interval.`;\n    fill($(\"drivers\"), forecast.drivers, (element, driver) => {\n      const label = document.createElement(\"span\"), impact = document.createElement(\"span\");\n      label.textContent = driver.label;\n      impact.textContent = `${signed(driver.impactPoints)} points`;\n      element.title = driver.evidence;\n      element.append(label, impact);\n    });\n    setControls(forecast.controls);\n    $(\"message\").hidden = true;\n    $(\"result\").hidden = false;\n    $(\"drivers-section\").hidden = false;\n    form.hidden = false;\n  }\n\n  async function recalculate() {\n    if (!canCallTools) return;\n    const args = {};\n    for (const key of CONTROL_KEYS) {\n      const value = Number(form.elements.namedItem(key).value);\n      if (value !== 100) args[key] = value;\n    }\n    const call = ++latestCall;\n    form.setAttribute(\"aria-busy\", \"true\");\n    try {\n      const result = await request(\"tools/call\", { name: TOOL_NAME, arguments: args });\n      if (call !== latestCall) return;\n      render(result);\n      const data = readPayload(result);\n      if (data?.forecast) {\n        // Keep the assistant's context in step with what the person set here.\n        request(\"ui/update-model-context\", { content: [{ type: \"text\", text:\n          `Road to Six forecast card: football-only Cowboys win probability ${percent(data.forecast.cowboysWinPercent)} `\n          + `(baseline ${percent(data.forecast.baselinePercent)}) with controls ${JSON.stringify(data.forecast.controls)}. `\n          + `Data version ${data.evidence.football.dataVersion}, read ${data.evidence.observedAt}. Educational analysis, not betting advice.` }] }).catch(() => {});\n      }\n    } catch (error) {\n      if (call === latestCall) showMessage(`The host could not complete the what-if request. ${error instanceof Error ? error.message : \"\"}`.trim());\n    } finally {\n      if (call === latestCall) form.removeAttribute(\"aria-busy\");\n    }\n  }\n\n  function applyContext(context) {\n    if (!context || typeof context !== \"object\") return;\n    if (context.theme === \"light\" || context.theme === \"dark\") document.documentElement.style.colorScheme = context.theme;\n    const variables = context.styles?.variables;\n    if (variables && typeof variables === \"object\") {\n      for (const [name, value] of Object.entries(variables)) {\n        if (/^--[a-z0-9-]+$/.test(name) && typeof value === \"string\") document.documentElement.style.setProperty(name, value);\n      }\n    }\n  }\n\n  window.addEventListener(\"message\", (event) => {\n    if (event.source !== host) return;\n    const message = event.data;\n    if (!message || message.jsonrpc !== \"2.0\") return;\n    if (message.method === undefined) {\n      const entry = pending.get(message.id);\n      if (!entry) return;\n      pending.delete(message.id);\n      if (message.error) entry.reject(new Error(String(message.error.message ?? \"Request failed\")));\n      else entry.resolve(message.result);\n      return;\n    }\n    if (message.id !== undefined) {\n      const known = message.method === \"ui/resource-teardown\" || message.method === \"ping\";\n      post(known ? { jsonrpc: \"2.0\", id: message.id, result: {} }\n        : { jsonrpc: \"2.0\", id: message.id, error: { code: -32601, message: \"Method not found\" } });\n      return;\n    }\n    const params = message.params ?? {};\n    if (message.method === \"ui/notifications/tool-input\") setControls(params.arguments);\n    else if (message.method === \"ui/notifications/tool-result\") render(params);\n    else if (message.method === \"ui/notifications/tool-cancelled\") showMessage(\"The forecast request was cancelled.\");\n    else if (message.method === \"ui/notifications/host-context-changed\") applyContext(params);\n  });\n\n  form.addEventListener(\"input\", (event) => {\n    const input = event.target;\n    if (!(input instanceof HTMLInputElement)) return;\n    input.nextElementSibling.textContent = `${Math.round(Number(input.value))}%`;\n    clearTimeout(debounce);\n    debounce = setTimeout(recalculate, 250);\n  });\n  $(\"reset\").addEventListener(\"click\", () => { setControls({}); clearTimeout(debounce); recalculate(); });\n  $(\"model-card\").addEventListener(\"click\", (event) => {\n    if (!canOpenLinks) return;\n    event.preventDefault();\n    request(\"ui/open-link\", { url: event.currentTarget.href }).catch(() => {});\n  });\n\n  if (typeof ResizeObserver === \"function\") {\n    new ResizeObserver(() => {\n      const box = document.documentElement.getBoundingClientRect();\n      notify(\"ui/notifications/size-changed\", { width: Math.ceil(box.width), height: Math.ceil(box.height) });\n    }).observe(document.documentElement);\n  }\n\n  if (host === window) return showMessage(\"Open this card inside an MCP Apps host to see a forecast.\");\n  request(\"ui/initialize\", {\n    appInfo: { name: \"road-to-six-forecast-card\", version: \"1.0.0\" },\n    appCapabilities: { availableDisplayModes: [\"inline\"] },\n    protocolVersion: APP_PROTOCOL_VERSION,\n  }).then((result) => {\n    canCallTools = Boolean(result?.hostCapabilities?.serverTools);\n    canOpenLinks = Boolean(result?.hostCapabilities?.openLinks);\n    applyContext(result?.hostContext);\n    if (!canCallTools) {\n      for (const element of form.elements) element.disabled = true;\n      $(\"controls-help\").textContent = \"This host does not let the card recalculate. Ask the assistant for a what-if scenario instead.\";\n    }\n    notify(\"ui/notifications/initialized\", {});\n  }).catch(() => showMessage(\"The host did not complete the card handshake.\"));\n})();\n</script>\n</body>\n</html>";
